(function (global) {
    // 1. Fungsi muat script yang lebih reliabel
    function loadScript(src) {
      return new Promise(function (resolve, reject) {
        // Cek apakah script sudah ada untuk menghindari duplikasi
        if (document.querySelector(`script[src="${src}"]`)) {
          return resolve();
        }
  
        var s = document.createElement("script");
        s.src = src;
        s.async = true; // Biarkan download paralel
  
        s.onload = () => {
          console.log(`%c[Loaded] ${src.split('/').pop()}`, "color: #00ff00");
          resolve();
        };
  
        s.onerror = () => reject(new Error("Gagal memuat script: " + src));
  
        document.head.appendChild(s);
      });
    }
  
    async function init() {
      // 2. Cek GSAP segera
      if (!global.gsap) {
        console.error("❌ GSAP tidak ditemukan! Pastikan GSAP diload sebelum bundle ini.");
        return;
      }
  
      try {
        console.log("%c🚀 Memulai loading SplitMotion Bundle...", "font-weight: bold; color: #3498db");
  
        // 3. Load CORE dulu secara sekuensial (wajib)
        await loadScript("https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/split-motion.min.js");
  
        // 4. Load MODUL secara paralel (lebih cepat)
        const modules = [
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/scramble.min.js",
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/pixelTwo.min.js",
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/marquee.min.js"
        ];
  
        await Promise.all(modules.map(src => loadScript(src)));
  
        // 5. Cek apakah objek myMotion akhirnya terbentuk
        if (global.myMotion && typeof global.myMotion.init === "function") {
          console.log("%c✅ Semua modul siap. Menginisialisasi...", "color: #2ecc71");
          global.SplitMotionBundleReady = true;
          global.myMotion.init();
        } else {
          throw new Error("Objek global.myMotion tidak ditemukan setelah loading.");
        }
  
      } catch (e) {
        console.error("❌ Loader error:", e.message);
      }
    }
  
    // 6. Gunakan DOMContentLoaded agar eksekusi lebih cepat (tidak menunggu gambar/video)
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", init);
    } else {
      init();
    }
  
  })(window);